fn max_subarray(xs: List[Int]) -> Int
  requires len(xs) > 0
  requires exists x in xs: x > 0
  ensures result > 0
  effects pure
  example max_subarray([1, -2, 3, 4, -1]) == 7
  example max_subarray([2, 2, -5, 1]) == 4
{
  match xs {
    [] => 0
    [h, ..t] => kadane_impl(t, h, h)
  }
}

fn kadane_impl(xs: List[Int], max_so_far: Int, max_ending_here: Int) -> Int
  requires len(xs) >= 0
  ensures result >= max_so_far
  effects pure
  example kadane_impl([], 7, 6) == 7
  example kadane_impl([3, 4, -1], 1, -1) == 7
{
  match xs {
    [] => max_so_far
    [h, ..t] => kadane_impl(t, if (if h > (max_ending_here + h) then h else (max_ending_here + h)) > max_so_far then (if h > (max_ending_here + h) then h else (max_ending_here + h)) else max_so_far, if h > (max_ending_here + h) then h else (max_ending_here + h))
  }
}

fn merge_sorted(xs: List[Int], ys: List[Int]) -> List[Int]
  requires sorted(xs) and sorted(ys)
  ensures sorted(result)
  ensures len(result) == len(xs) + len(ys)
  ensures forall x in xs: contains(result, x)
  ensures forall y in ys: contains(result, y)
  effects pure
  example merge_sorted([1, 4, 9], [2, 3]) == [1, 2, 3, 4, 9]
  example merge_sorted([], [5, 6]) == [5, 6]
  example merge_sorted([1, 2], []) == [1, 2]
  example merge_sorted([], []) == []
  example merge_sorted([1, 3, 5], [2, 4]) == [1, 2, 3, 4, 5]
{
  match xs {
    [] => ys
    [x, ..xs_rest] => match ys {
      [] => xs
      [y, ..ys_rest] => if x <= y
        then [x] ++ merge_sorted(xs_rest, ys)
        else [y] ++ merge_sorted(xs, ys_rest)
    }
  }
}

fn count_occurrences(xs: List[Int], x: Int) -> Int
  requires len(xs) >= 0
  ensures result >= 0 and result == count(xs, x)
  effects pure
  example count_occurrences([1, 2, 2, 3], 2) == 2
  example count_occurrences([], 1) == 0
  example count_occurrences([1, 1, 1], 1) == 3
{
  match xs {
    [] => 0
    [h, ..t] =>
      if h == x
      then 1 + count_occurrences(t, x)
      else count_occurrences(t, x)
  }
}

fn is_more_frequent(xs: List[Int], a: Int, b: Option[Int]) -> Bool
  requires contains(xs, a)
  requires match b {
    None => true
    Some(b_val) => contains(xs, b_val)
  }
  ensures match b {
    None => result == true
    Some(b_val) => result == (count(xs, a) > count(xs, b_val))
  }
  effects pure
  example is_more_frequent([1, 2, 2, 3], 2, None) == true
  example is_more_frequent([1, 2, 2, 3], 1, Some(2)) == false
  example is_more_frequent([1, 2, 2, 3], 2, Some(1)) == true
{
  match b {
    None => true
    Some(b_val) => count_occurrences(xs, a) > count_occurrences(xs, b_val)
  }
}

fn find_max_helper(original: List[Int], remaining: List[Int], best: Option[Int]) -> Option[Int]
  requires forall c in remaining: contains(original, c)
  requires match best {
    None => true
    Some(b) => contains(original, b)
  }
  ensures match result {
    None => len(original) == 0
    Some(x) => contains(original, x) and forall y in original: y == x or count(original, x) > count(original, y)
  }
  effects pure
  example find_max_helper([1, 2, 2, 3], [1, 2, 3], None) == Some(2)
  example find_max_helper([], [], None) == None
  example find_max_helper([5], [5], None) == Some(5)
{
  match remaining {
    [] => best
    [h, ..t] =>
      if is_more_frequent(original, h, best)
      then find_max_helper(original, t, Some(h))
      else find_max_helper(original, t, best)
  }
}

fn most_frequent(xs: List[Int]) -> Option[Int]
  requires len(xs) == 0 or exists x in xs: forall y in xs: y == x or count(xs, x) > count(xs, y)
  ensures match result {
    None => len(xs) == 0
    Some(x) => contains(xs, x) and forall y in xs: y == x or count(xs, x) > count(xs, y)
  }
  effects pure
  example most_frequent([]) == None
  example most_frequent([1, 2, 2, 3]) == Some(2)
  example most_frequent([5]) == Some(5)
{
  find_max_helper(xs, xs, None)
}

fn cnt(xs: List[Int], x: Int) -> Int
  requires len(xs) >= 0
  ensures result == count(xs, x)
  effects pure
  example cnt([1, 2, 2, 3], 2) == 2
  example cnt([], 5) == 0
{
  match xs {
    [] => 0
    [h, ..t] => if h == x then 1 + cnt(t, x) else cnt(t, x)
  }
}

fn le_all(xs: List[Int], all: List[Int], b: Int) -> Bool
  requires len(xs) >= 0
  ensures result == (forall x in xs: count(all, x) <= count(all, b))
  effects pure
  example le_all([1, 2], [1, 2, 2], 2) == true
  example le_all([1, 2], [1, 2, 2], 1) == false
  example le_all([], [1], 1) == true
{
  match xs {
    [] => true
    [h, ..t] => cnt(all, h) <= cnt(all, b) and le_all(t, all, b)
  }
}

fn is_best(xs: List[Int], all: List[Int], r: Option[Int]) -> Bool
  requires len(xs) >= 0
  ensures not (len(xs) == 0) or result == (r == None)
  effects pure
  example is_best([], [], None) == true
  example is_best([1, 2], [1, 2, 2], Some(2)) == true
  example is_best([1, 2], [1, 2, 2], Some(1)) == false
{
  match r {
    None => xs == []
    Some(b) => cnt(xs, b) > 0 and le_all(xs, all, b)
  }
}

fn max_count(xs: List[Int], all: List[Int]) -> Option[Int]
  requires len(xs) >= 0
  ensures is_best(xs, all, result)
  effects pure
  example max_count([1, 2, 3], [1, 2, 2, 3]) == Some(2)
  example max_count([], [1]) == None
{
  match xs {
    [] => None
    [h, ..t] => match max_count(t, all) {
      None => Some(h)
      Some(b) => if cnt(all, h) >= cnt(all, b) then Some(h) else Some(b)
    }
  }
}

fn most_frequent(xs: List[Int]) -> Option[Int]
  requires len(xs) >= 0
  ensures is_best(xs, xs, result)
  effects pure
  example most_frequent([1, 2, 2, 3]) == Some(2)
  example most_frequent([]) == None
  example most_frequent([7]) == Some(7)
  example most_frequent([3, 3, 1, 3, 2]) == Some(3)
{
  max_count(xs, xs)
}

fn nth(xs: List[Int], i: Int) -> Option[Int]
  requires i >= 0
  ensures (i < len(xs)) or (result == None)
  ensures (i >= len(xs)) or (result != None)
  effects pure
  example nth([5, 6, 7], 1) == Some(6)
  example nth([5, 6, 7], 3) == None
  example nth([], 0) == None
  example nth([42], 0) == Some(42)
  example nth([1, 2, 3], 0) == Some(1)
{
  if i == 0 then match xs {
    [] => None
    [h, ..t] => Some(h)
  } else match xs {
    [] => None
    [_, ..t] => nth(t, i - 1)
  }
}

fn max_element(xs: List[Int]) -> Option[Int]
  requires len(xs) > 0
  ensures match result {
    None => false
    Some(m) => contains(xs, m) and forall x in xs: x <= m
  }
  effects pure
  example max_element([3, 9, 1]) == Some(9)
  example max_element([5]) == Some(5)
{
  match xs {
    [] => None
    [h, ..t] => 
      match t {
        [] => Some(h)
        _ => match max_element(t) {
          None => Some(h)
          Some(m) => if h > m then Some(h) else Some(m)
        }
      }
  }
}

fn remove_element(xs: List[Int], v: Int) -> List[Int]
  requires contains(xs, v)
  ensures len(result) == len(xs) - 1
  effects pure
  example remove_element([3, 9, 1], 9) == [3, 1]
  example remove_element([1, 2], 2) == [1]
  example remove_element([5], 5) == []
{
  match xs {
    [] => []
    [h, ..t] => 
      if h == v then t 
      else [h] ++ remove_element(t, v)
  }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures match result {
    None => len(xs) < 2
    Some(x) => contains(xs, x) and exists y in xs: y > x
  }
  effects pure
  example second_largest([3, 9, 1]) == Some(3)
  example second_largest([4]) == None
  example second_largest([1, 2]) == Some(1)
  example second_largest([]) == None
{
  match xs {
    [] => None
    [_, ..t] => 
      match t {
        [] => None
        _ => match max_element(xs) {
          None => None
          Some(m) => max_element(remove_element(xs, m))
        }
      }
  }
}

fn zip_sum(xs: List[Int], ys: List[Int]) -> List[Int]
  requires len(xs) == len(ys)
  ensures len(result) == len(xs)
  effects pure
  example zip_sum([], []) == []
  example zip_sum([1, 2, 3], [10, 20, 30]) == [11, 22, 33]
{
  match xs {
    [] => []
    [h_x, ..t_x] => 
      match ys {
        [h_y, ..t_y] => [h_x + h_y] ++ zip_sum(t_x, t_y)
        [] => []
      }
  }
}

fn zip_sum(xs: List[Int], ys: List[Int]) -> List[Int]
  requires len(xs) == len(ys)
  ensures len(result) == len(xs)
  ensures forall i in 0..len(result): result[i] == xs[i] + ys[i]
  effects pure
  example zip_sum([1, 2, 3], [10, 20, 30]) == [11, 22, 33]
  example zip_sum([], []) == []
  example zip_sum([5], [-5]) == [0]
  example zip_sum([-1, 0], [1, 7]) == [0, 7]
{
  match xs {
    [] => []
    [a, ..s] => match ys {
      [] => []
      [b, ..t] => [a + b] ++ zip_sum(s, t)
    }
  }
}

fn zip_sum(xs: List[Int], ys: List[Int]) -> List[Int]
  requires (len(xs) == len(ys))
  ensures (len(result) == len(xs))
  ensures forall i in 0..len(result): (result[i] == (xs[i] + ys[i]))
  effects pure
  example (zip_sum([1, 2, 3], [10, 20, 30]) == [11, 22, 33])
  example (zip_sum([], []) == [])
  example (zip_sum([5], [-5]) == [0])
  example (zip_sum([-1, 0], [1, 7]) == [0, 7])
{
  match xs {
    [] => []
    [h1, ..t1] => match ys {
      [] => []
      [h2, ..t2] => [h1 + h2] ++ zip_sum(t1, t2)
    }
  }
}

fn get_at(xs: List[Int], i: Int) -> Option[Int]
  requires ((i >= 0) and (i < len(xs)))
  ensures (result != None)
  effects pure
  example (get_at([10, 20, 30], 0) == Some(10))
  example (get_at([10, 20, 30], 1) == Some(20))
  example (get_at([10, 20, 30], 2) == Some(30))
{
  match xs { [] => None [h, ..t] => if (i == 0) then Some(h) else get_at(t, (i - 1)) }
}

fn index_of(xs: List[Int], x: Int) -> Int
  requires contains(xs, x)
  ensures ((result >= 0) and (result < len(xs)))
  ensures (get_at(xs, result) == Some(x))
  effects pure
  example (index_of([4, 7, 9], 7) == 1)
  example (index_of([3, 3, 3], 3) == 0)
{
  match xs { [] => 1 [h, ..t] => if (h == x) then 0 else (1 + index_of(t, x)) }
}

