  effects pure
  example (is_more_frequent([1, 2, 2, 3], 2, None) == true)
  example (is_more_frequent([1, 2, 2, 3], 1, Some(2)) == false)
  example (is_more_frequent([1, 2, 2, 3], 2, Some(1)) == true)
{
  match b { None => true Some(b_val) => (count_occurrences(xs, a) > count_occurrences(xs, b_val)) }
}

fn find_max_helper(original: List[Int], remaining: List[Int], best: Option[Int]) -> Option[Int]
  requires forall c in remaining: contains(original, c)
  requires match best { None => true Some(b) => contains(original, b) }
  ensures match result { None => (len(original) == 0) Some(x) => (contains(original, x) and (forall y in original: ((y == x) or (count(original, x) > count(original, y))))) }
  effects pure
  example (find_max_helper([1, 2, 2, 3], [1, 2, 3], None) == Some(2))
  example (find_max_helper([], [], None) == None)
  example (find_max_helper([5], [5], None) == Some(5))
{
  match remaining { [] => best [h, ..t] => if is_more_frequent(original, h, best) then find_max_helper(original, t, Some(h)) else find_max_helper(original, t, best) }
}

